package main
import("bytes";"encoding/hex";"flag";"os";"path/filepath";"testing")
const eg_trusted_tone_hex=""
func isolated_generation(t *testing.T,matrix string)decay_generation{
 t.Helper();old:=flag.CommandLine;flag.CommandLine=flag.NewFlagSet("eg-test",flag.ContinueOnError);t.Cleanup(func(){flag.CommandLine=old});data,e:=hex.DecodeString(eg_trusted_tone_hex);if e!=nil{t.Fatal(e)};d:=t.TempDir();base:=filepath.Join(d,"base.bin");if e=os.WriteFile(base,data,0600);e!=nil{t.Fatal(e)};return decay_generation{base:base,output:filepath.Join(d,"programs"),profile:"all",carrier:"auto",matrix:matrix,last:-1,complements:true}
}
func TestTrustedBaseContamination(t *testing.T){
 for _,suffix:=range [][]byte{{1,8,64},{1,0x21,0xc7},{1,0x19,1},{1,0x99,31}}{t.Run(hex.EncodeToString(suffix),func(t *testing.T){j:=isolated_generation(t,"ks-kc-main");d,e:=os.ReadFile(j.base);if e!=nil{t.Fatal(e)};d=append(append(append([]byte{},d[:len(d)-4]...),suffix...),d[len(d)-4:]...);if e=os.WriteFile(j.base,d,0600);e!=nil{t.Fatal(e)};if e=j.run();e==nil{t.Fatal("contaminated base accepted")};if _,e=os.Stat(j.output);!os.IsNotExist(e){t.Fatal("rejected input created output")}})}
}
func TestGeneratorExclusiveOutput(t *testing.T){j:=isolated_generation(t,"ks-kc-carriers");if e:=j.run();e!=nil{t.Fatal(e)};p:=filepath.Join(j.output,"cases.json");before,_:=os.ReadFile(p);if e:=j.run();e==nil{t.Fatal("reused output accepted")};after,_:=os.ReadFile(p);if !bytes.Equal(before,after){t.Fatal("owned output changed")}}
func TestFixedOverrideRejected(t *testing.T){j:=isolated_generation(t,"ks-kc-main");flag.CommandLine.String("first","","test override");if e:=flag.CommandLine.Parse([]string{"-first","0"});e!=nil{t.Fatal(e)};if e:=j.run();e==nil{t.Fatal("fixed override accepted")}}
func TestCarrierLiteralEvents(t *testing.T){j:=isolated_generation(t,"ks-kc-carriers");if e:=j.run();e!=nil{t.Fatal(e)};for _,name:=range []string{"carrier-held-kc3e-mul8","carrier-held-kc41-mul8"}{v,e:=os.ReadFile(filepath.Join(j.output,name+"-event.bin"));if e!=nil{t.Fatal(e)};if !bytes.Equal(v,[]byte{2,0,1,0}){t.Fatalf("%s event %x",name,v)}}}
